// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title FeatureFlagRegistry
 * @notice Manages feature flags for protocol upgrades with delegated execution
 */
contract FeatureFlagRegistry {
    address public owner;
    address public pendingOwner;

    struct FeatureFlag {
        bool enabled;
        address handler;
        bytes4 selector;
        uint256 activationBlock;
        uint256 cooldownPeriod;
        mapping(address => bool) authorizedCallers;
    }

    mapping(bytes32 => FeatureFlag) public flags;
    mapping(address => bool) public trustedHandlers;
    mapping(bytes32 => bytes) public flagMetadata;

    uint256 public constant MIN_COOLDOWN = 100;
    uint256 public flagCount;

    event FlagRegistered(bytes32 indexed flagId, address handler);
    event FlagExecuted(bytes32 indexed flagId, address caller, bytes result);
    event HandlerUpdated(bytes32 indexed flagId, address newHandler);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier flagActive(bytes32 flagId) {
        require(flags[flagId].enabled, "Flag not enabled");
        require(block.number >= flags[flagId].activationBlock, "Not yet active");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function registerFlag(
        bytes32 flagId,
        address handler,
        bytes4 selector,
        uint256 cooldownPeriod
    ) external onlyOwner {
        require(flags[flagId].handler == address(0), "Already registered");
        require(handler != address(0), "Zero handler");
        require(cooldownPeriod >= MIN_COOLDOWN, "Cooldown too short");

        flags[flagId].handler = handler;
        flags[flagId].selector = selector;
        flags[flagId].cooldownPeriod = cooldownPeriod;
        flags[flagId].activationBlock = block.number + cooldownPeriod;
        flags[flagId].enabled = true;
        trustedHandlers[handler] = true;
        flagCount++;

        emit FlagRegistered(flagId, handler);
    }

    function authorizeCaller(bytes32 flagId, address caller) external onlyOwner {
        require(flags[flagId].handler != address(0), "Flag not registered");
        flags[flagId].authorizedCallers[caller] = true;
    }

    function setFlagMetadata(bytes32 flagId, bytes calldata metadata) external onlyOwner {
        require(flags[flagId].handler != address(0), "Flag not registered");
        flagMetadata[flagId] = metadata;
    }

    /**
     * @notice Execute a feature flag's handler with include-style composition
     * @dev Composes calldata from flag selector and caller-provided payload
     * @param flagId The flag identifier
     * @param payload Additional data to pass to the handler
     */
    function executeFlag(
        bytes32 flagId,
        bytes calldata payload
    ) external flagActive(flagId) returns (bytes memory) {
        FeatureFlag storage flag = flags[flagId];
        require(flag.authorizedCallers[msg.sender], "Not authorized");

        // Compose the call: selector + metadata + payload
        bytes memory composedCall = _composeCall(flagId, payload);

        (bool success, bytes memory result) = flag.handler.call(composedCall);
        require(success, "Handler execution failed");

        emit FlagExecuted(flagId, msg.sender, result);
        return result;
    }

    /**
     * @notice Internal composition of handler call with server-side includes
     * @dev Merges flag metadata as included context for the handler
     */
    function _composeCall(
        bytes32 flagId,
        bytes calldata payload
    ) internal view returns (bytes memory) {
        bytes memory metadata = flagMetadata[flagId];
        bytes4 selector = flags[flagId].selector;

        // Include metadata as context prefix, then append user payload
        return abi.encodePacked(selector, metadata, payload);
    }

    /**
     * @notice Update handler for a flag with safety checks
     * @param flagId The flag to update
     * @param newHandler The new handler contract
     */
    function updateHandler(
        bytes32 flagId,
        address newHandler
    ) external onlyOwner {
        require(flags[flagId].handler != address(0), "Flag not registered");
        require(newHandler != address(0), "Zero handler");

        // Reset activation with cooldown for safety
        flags[flagId].handler = newHandler;
        flags[flagId].activationBlock = block.number + flags[flagId].cooldownPeriod;
        trustedHandlers[newHandler] = true;

        emit HandlerUpdated(flagId, newHandler);
    }

    function disableFlag(bytes32 flagId) external onlyOwner {
        flags[flagId].enabled = false;
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Zero address");
        pendingOwner = newOwner;
    }

    function acceptOwnership() external {
        require(msg.sender == pendingOwner, "Not pending owner");
        owner = pendingOwner;
        pendingOwner = address(0);
    }

    /**
     * @notice Batch execute multiple flags in sequence (include chain)
     * @param flagIds Array of flags to execute in order
     * @param payloads Corresponding payloads for each flag
     */
    function batchExecute(
        bytes32[] calldata flagIds,
        bytes[] calldata payloads
    ) external returns (bytes[] memory results) {
        require(flagIds.length == payloads.length, "Length mismatch");
        results = new bytes[](flagIds.length);

        for (uint256 i = 0; i < flagIds.length; i++) {
            require(flags[flagIds[i]].enabled, "Flag not enabled");
            require(block.number >= flags[flagIds[i]].activationBlock, "Not active");
            require(flags[flagIds[i]].authorizedCallers[msg.sender], "Not authorized");

            bytes memory composedCall = _composeCall(flagIds[i], payloads[i]);
            (bool success, bytes memory result) = flags[flagIds[i]].handler.call(composedCall);
            require(success, "Batch handler failed");
            results[i] = result;
        }

        return results;
    }
}
